import { type DataGridColumn, TreeGrid, type TreeGridRow } from '@design-schema/react';

const COLUMNS: DataGridColumn[] = [
  { key: 'account', header: 'Account', isRowHeader: true, width: 240 },
  { key: 'code', header: 'Code', width: 100 },
  { key: 'balance', header: 'Balance', align: 'end', sortable: true },
];

const DATA: TreeGridRow[] = [
  {
    id: 'assets',
    account: 'Assets',
    code: '1000',
    balance: 1400,
    children: [
      { id: 'cash', account: 'Cash', code: '1010', balance: 400 },
      {
        id: 'stock',
        account: 'Stock',
        code: '1020',
        balance: 1000,
        children: [
          { id: 'raw', account: 'Raw materials', code: '1021', balance: 600 },
          { id: 'finished', account: 'Finished goods', code: '1022', balance: 400 },
        ],
      },
    ],
  },
  {
    id: 'liabilities',
    account: 'Liabilities',
    code: '2000',
    balance: 300,
    children: [{ id: 'payable', account: 'Accounts payable', code: '2010', balance: 300 }],
  },
  { id: 'equity', account: 'Equity', code: '3000', balance: 1100 },
];

<TreeGrid
  caption="Chart of accounts"
  columns={COLUMNS}
  data={DATA}
  defaultExpanded={['assets']}
/>

snippets.lit:
import '@design-schema/lit';
import { html } from 'lit';
import type { DataGridColumn, TreeGridRow } from '@design-schema/lit';

const accountColumns: DataGridColumn[] = [
  { key: 'name', header: 'Account', isRowHeader: true, width: 240, resizable: true },
  { key: 'code', header: 'Code', width: 96 },
  { key: 'balance', header: 'Balance', align: 'end', sortable: true, editable: true, editor: 'number', width: 144 },
];

const accountsData: TreeGridRow[] = [
  {
    id: 'assets',
    name: 'Assets',
    code: '1000',
    balance: 125000,
    children: [
      {
        id: 'current-assets',
        name: 'Current assets',
        code: '1100',
        balance: 85000,
        children: [
          { id: 'cash', name: 'Cash', code: '1110', balance: 50000 },
          { id: 'receivables', name: 'Accounts receivable', code: '1120', balance: 35000 },
        ],
      },
      {
        id: 'fixed-assets',
        name: 'Fixed assets',
        code: '1200',
        balance: 40000,
        children: [{ id: 'equipment', name: 'Equipment', code: '1210', balance: 40000 }],
      },
    ],
  },
  {
    id: 'liabilities',
    name: 'Liabilities',
    code: '2000',
    balance: 42000,
    children: [{ id: 'payables', name: 'Accounts payable', code: '2100', balance: 42000 }],
  },
  { id: 'equity', name: 'Equity', code: '3000', balance: 83000, children: 'lazy' },
];

html`
  <ds-tree-grid
    caption="Chart of accounts"
    .columns=${accountColumns}
    .data=${accountsData}
    .defaultExpanded=${['assets', 'current-assets']}
  ></ds-tree-grid>
`;

